grid=[[8,8,8,8,5,8,8,8,8,8,8,8,8,5,8,8,8,8,5,8,8,8,8,8,5,8,8],[8,5,5,8,8,8,8,8,5,8,8,5,8,8,8,8,8,8,8,5,8,8,8,8,8,8,8],[8,8,8,8,8,8,8,8,8,8,8,5,8,8,8,8,8,8,8,8,5,8,8,5,8,8,8]]
out=[r[:] for r in grid]
# horizontal fill between leftmost and rightmost 5 in each row
for i,r in enumerate(grid):
    cols=[j for j,c in enumerate(r) if c==5]
    if len(cols)>=2:
        for j in range(min(cols),max(cols)+1):
            if out[i][j]!=5: out[i][j]=3
# vertical fill between top and bottom 5 in each column
for j in range(len(grid[0])):
    rows=[i for i in range(len(grid)) if grid[i][j]==5]
    if len(rows)>=2:
        for i in range(min(rows),max(rows)+1):
            if out[i][j]!=5: out[i][j]=3
for r in out: print(r)
